// Dependency-free tar packer and parallel extractor for the node_modules restore benchmark. It
// must not import anything from node_modules, because it runs before they exist.
//
//   node archive.ts pack --root DIR --list FILE [--level N] --out [FLAGS@]PATH [--out ...]
//     Reads the files of FILE (one path relative to DIR per line) once, and writes one zstd
//     compressed tar per --out. FLAGS, joined with '+':
//       dedup      store byte-identical files once, and their copies as hard links
//       dedupbig   the same, only for files of 16 KB or more
//       nomap      skip source maps (*.js.map, *.d.ts.map, ...)
//       nocopilot  skip extensions/copilot/
//       nolong     compress without long distance matching, for decoders that limit the window size
//   node archive.ts extract --archive PATH --dest DIR [--concurrency N] [--decoder cli|node] [--clone-duplicates true] [--clone-list FILE] [--stats FILE]
//     Creates the files of the archive with up to N file system operations in flight. Set
//     UV_THREADPOOL_SIZE to N as well: Node runs file system operations on that thread pool.
//     --clone-duplicates copies files of 64 KB or more whose content it already wrote from the
//     first copy, which clones its blocks where CopyFile does (ReFS). --clone-list writes those
//     copies as "original<TAB>copy" lines to FILE instead, for a tool that clones them.
//   node archive.ts count --archive PATH [--stats FILE]
//     Counts the entries of the archive by kind.
//   node archive.ts move --from DIR --to DIR --roots FILE
//     Renames the node_modules folders listed in FILE (paths relative to both folders) from DIR
//     into the same paths of the other DIR, on the same volume, skipping those that exist.
//   node archive.ts read --root DIR
//     Reads every file of the node_modules folders of DIR, to time reading them.

import { spawn, type ChildProcess } from 'child_process';
import { createHash } from 'crypto';
import { once } from 'events';
import * as fs from 'fs';
import * as path from 'path';
import type { Readable } from 'stream';
import * as zlib from 'zlib';

const BLOCK = 512;
const DEDUP_BIG = 16 * 1024;
// NTFS allows 1024 names per file; stay well below that for ReFS and APFS too.
const MAX_LINKS = 256;
const MAX_INFLIGHT_BYTES = 512 * 1024 * 1024;
const SOURCE_MAP = /\.(?:[cm]?js|[cm]?ts|css)\.map$/i;
const COPILOT = 'extensions/copilot/';

type Args = Map<string, string[]>;

function parseArgs(argv: readonly string[]): Args {
	const args: Args = new Map();
	for (let i = 0; i < argv.length; i += 2) {
		if (!argv[i].startsWith('--') || i + 1 >= argv.length) {
			throw new Error(`Unexpected argument: ${argv[i]}`);
		}
		const key = argv[i].slice(2);
		args.set(key, [...(args.get(key) ?? []), argv[i + 1]]);
	}
	return args;
}

function arg(args: Args, name: string, fallback?: string): string {
	const value = args.get(name)?.[0] ?? fallback;
	if (value === undefined) {
		throw new Error(`Missing --${name}`);
	}
	return value;
}

//#region pack

interface PackOutput {
	readonly file: string;
	readonly dedupMin: number;
	readonly noMap: boolean;
	readonly noCopilot: boolean;
	readonly zstd: ChildProcess;
	readonly exit: Promise<unknown[]>;
	readonly seen: Map<string, { name: string; links: number }>;
	readonly stats: { files: number; hardlinks: number; symlinks: number; bytes: number };
}

interface PackItem {
	readonly name: string;
	readonly mode: number;
	readonly data?: Buffer;
	readonly hash?: string;
	readonly symlinkTarget?: string;
}

function createOutput(spec: string, level: number): PackOutput {
	const at = spec.indexOf('@');
	const flags = new Set(at === -1 ? [] : spec.slice(0, at).split('+'));
	const file = at === -1 ? spec : spec.slice(at + 1);
	for (const flag of flags) {
		if (!['dedup', 'dedupbig', 'nomap', 'nocopilot', 'nolong'].includes(flag)) {
			throw new Error(`Unknown flag: ${flag}`);
		}
	}
	fs.mkdirSync(path.dirname(file), { recursive: true });
	const zstd = spawn('zstd', ['-q', `-${level}`, '-T0', ...(flags.has('nolong') ? [] : ['--long=30']), '-f', '-o', file, '-'], { stdio: ['pipe', 'inherit', 'inherit'] });
	return {
		file,
		dedupMin: flags.has('dedup') ? 1 : flags.has('dedupbig') ? DEDUP_BIG : Infinity,
		noMap: flags.has('nomap'),
		noCopilot: flags.has('nocopilot'),
		zstd,
		exit: once(zstd, 'exit'),
		seen: new Map(),
		stats: { files: 0, hardlinks: 0, symlinks: 0, bytes: 0 },
	};
}

function writeOctal(header: Buffer, offset: number, length: number, value: number): void {
	const text = value.toString(8).padStart(length - 1, '0');
	if (text.length > length - 1) {
		throw new Error(`Value too large for a tar header: ${value}`);
	}
	header.write(text, offset, length - 1, 'ascii');
	header[offset + length - 1] = 0;
}

function tarHeader(name: string, type: string, size: number, mode: number, linkname: string): Buffer {
	const header = Buffer.alloc(BLOCK);
	header.write(name, 0, 100, 'utf8');
	writeOctal(header, 100, 8, mode);
	writeOctal(header, 108, 8, 0);
	writeOctal(header, 116, 8, 0);
	writeOctal(header, 124, 12, size);
	writeOctal(header, 136, 12, 0);
	header.fill(0x20, 148, 156);
	header.write(type, 156, 1, 'ascii');
	header.write(linkname, 157, 100, 'utf8');
	header.write('ustar\0', 257, 6, 'ascii');
	header.write('00', 263, 2, 'ascii');
	let checksum = 0;
	for (let i = 0; i < BLOCK; i++) {
		checksum += header[i];
	}
	header.write(checksum.toString(8).padStart(6, '0'), 148, 6, 'ascii');
	header[154] = 0;
	header[155] = 0x20;
	return header;
}

function paxRecord(key: string, value: string): string {
	const length = Buffer.byteLength(` ${key}=${value}\n`);
	let total = length + String(length).length;
	if (String(total).length !== String(length).length) {
		total = length + String(total).length;
	}
	return `${total} ${key}=${value}\n`;
}

function padding(size: number): Buffer {
	return Buffer.alloc((BLOCK - size % BLOCK) % BLOCK);
}

async function write(output: PackOutput, chunk: Buffer): Promise<void> {
	if (chunk.length && !output.zstd.stdin!.write(chunk)) {
		await once(output.zstd.stdin!, 'drain');
	}
}

async function writeEntry(output: PackOutput, name: string, type: string, mode: number, linkname: string, data?: Buffer): Promise<void> {
	const size = data?.length ?? 0;
	const records: string[] = [];
	if (Buffer.byteLength(name) > 100) {
		records.push(paxRecord('path', name));
	}
	if (Buffer.byteLength(linkname) > 100) {
		records.push(paxRecord('linkpath', linkname));
	}
	if (records.length) {
		const body = Buffer.from(records.join(''), 'utf8');
		await write(output, tarHeader('PaxHeader', 'x', body.length, 0o644, ''));
		await write(output, body);
		await write(output, padding(body.length));
	}
	await write(output, tarHeader(name, type, size, mode, linkname));
	if (data) {
		await write(output, data);
		await write(output, padding(size));
	}
}

async function addItem(output: PackOutput, item: PackItem): Promise<void> {
	if ((output.noCopilot && item.name.startsWith(COPILOT)) || (output.noMap && SOURCE_MAP.test(item.name))) {
		return;
	}
	if (item.symlinkTarget !== undefined) {
		output.stats.symlinks++;
		return writeEntry(output, item.name, '2', 0o777, item.symlinkTarget);
	}
	const data = item.data!;
	if (data.length >= output.dedupMin) {
		// Hard links share their permissions, so only files with the same mode can share content
		const key = `${item.mode}:${item.hash}`;
		const previous = output.seen.get(key);
		if (previous && previous.links < MAX_LINKS) {
			previous.links++;
			output.stats.hardlinks++;
			return writeEntry(output, item.name, '1', item.mode, previous.name);
		}
		output.seen.set(key, { name: item.name, links: 0 });
	}
	output.stats.files++;
	output.stats.bytes += data.length;
	return writeEntry(output, item.name, '0', item.mode, '', data);
}

async function readItem(root: string, name: string, hash: boolean): Promise<PackItem | undefined> {
	const file = path.join(root, name);
	let stat: fs.Stats;
	try {
		stat = await fs.promises.lstat(file);
	} catch {
		return undefined;
	}
	if (stat.isSymbolicLink()) {
		return { name, mode: 0o777, symlinkTarget: await fs.promises.readlink(file) };
	}
	if (!stat.isFile()) {
		return undefined;
	}
	const data = await fs.promises.readFile(file);
	return {
		name,
		mode: process.platform === 'win32' ? 0o644 : stat.mode & 0o777,
		data,
		hash: hash ? createHash('sha1').update(data).digest('hex') : undefined,
	};
}

async function pack(args: Args): Promise<void> {
	const root = path.resolve(arg(args, 'root'));
	const names = fs.readFileSync(arg(args, 'list'), 'utf8').split(/\r?\n/).filter(Boolean);
	const level = Number(arg(args, 'level', '3'));
	const outputs = (args.get('out') ?? []).map(spec => createOutput(spec, level));
	if (!outputs.length) {
		throw new Error('Missing --out');
	}
	const hash = outputs.some(output => output.dedupMin !== Infinity);
	const start = performance.now();
	const batchSize = 128;
	for (let i = 0; i < names.length; i += batchSize) {
		const items = await Promise.all(names.slice(i, i + batchSize).map(name => readItem(root, name, hash)));
		for (const item of items) {
			if (item) {
				for (const output of outputs) {
					await addItem(output, item);
				}
			}
		}
	}
	for (const output of outputs) {
		await write(output, Buffer.alloc(BLOCK * 2));
		output.zstd.stdin!.end();
	}
	for (const output of outputs) {
		const [code] = await output.exit;
		if (code !== 0) {
			throw new Error(`zstd exited with ${code} for ${output.file}`);
		}
		console.log(`${output.file}: ${fs.statSync(output.file).size} bytes, ${JSON.stringify(output.stats)}`);
	}
	console.log(`Packed ${names.length} paths in ${((performance.now() - start) / 1000).toFixed(1)}s`);
}

//#endregion

//#region extract

interface TarEntry {
	readonly type: string;
	readonly name: string;
	readonly linkname: string;
	readonly mode: number;
	readonly data?: Buffer;
}

class ByteQueue {
	private readonly chunks: Buffer[] = [];
	private offset = 0;
	length = 0;

	push(chunk: Buffer): void {
		this.chunks.push(chunk);
		this.length += chunk.length;
	}

	take(size: number): Buffer {
		if (size === 0) {
			return Buffer.alloc(0);
		}
		const first = this.chunks[0];
		if (first.length - this.offset >= size) {
			const result = first.subarray(this.offset, this.offset + size);
			this.advance(size);
			return result;
		}
		const result = Buffer.allocUnsafe(size);
		let written = 0;
		while (written < size) {
			const chunk = this.chunks[0];
			const count = Math.min(size - written, chunk.length - this.offset);
			chunk.copy(result, written, this.offset, this.offset + count);
			written += count;
			this.advance(count);
		}
		return result;
	}

	skip(size: number): void {
		while (size > 0) {
			const count = Math.min(size, this.chunks[0].length - this.offset);
			this.advance(count);
			size -= count;
		}
	}

	private advance(count: number): void {
		this.offset += count;
		this.length -= count;
		if (this.offset === this.chunks[0].length) {
			this.chunks.shift();
			this.offset = 0;
		}
	}
}

function cString(buffer: Buffer): string {
	const end = buffer.indexOf(0);
	return buffer.toString('utf8', 0, end === -1 ? buffer.length : end);
}

function parseNumber(header: Buffer, offset: number, length: number): number {
	if (header[offset] & 0x80) {
		// GNU base-256 encoding
		let value = header[offset] & 0x7f;
		for (let i = 1; i < length; i++) {
			value = value * 256 + header[offset + i];
		}
		return value;
	}
	const text = header.toString('ascii', offset, offset + length).replace(/\0.*$/s, '').trim();
	return text ? parseInt(text, 8) : 0;
}

function isEndBlock(header: Buffer): boolean {
	return header[0] === 0 && header[156] === 0 && header.every(byte => byte === 0);
}

async function* readTar(stream: AsyncIterable<Buffer>, onPax?: (records: ReadonlyMap<string, string>) => void): AsyncGenerator<TarEntry> {
	const queue = new ByteQueue();
	const iterator = stream[Symbol.asyncIterator]();
	const fill = async (size: number): Promise<void> => {
		while (queue.length < size) {
			const next = await iterator.next();
			if (next.done) {
				throw new Error('Unexpected end of archive');
			}
			queue.push(next.value);
		}
	};
	let pax = new Map<string, string>();
	let longName: string | undefined;
	let longLink: string | undefined;
	while (true) {
		await fill(BLOCK);
		const header = queue.take(BLOCK);
		if (isEndBlock(header)) {
			return;
		}
		const type = header[156] === 0 ? '0' : String.fromCharCode(header[156]);
		const size = pax.has('size') ? Number(pax.get('size')) : parseNumber(header, 124, 12);
		const padded = size + (BLOCK - size % BLOCK) % BLOCK;
		await fill(padded);
		if (type === 'x' || type === 'g' || type === 'L' || type === 'K') {
			const body = Buffer.from(queue.take(padded).subarray(0, size));
			if (type === 'x') {
				let index = 0;
				while (index < body.length) {
					const space = body.indexOf(0x20, index);
					const length = Number(body.toString('ascii', index, space));
					const record = body.toString('utf8', space + 1, index + length - 1);
					const equals = record.indexOf('=');
					pax.set(record.slice(0, equals), record.slice(equals + 1));
					index += length;
				}
				onPax?.(pax);
			} else if (type === 'L') {
				longName = cString(body);
			} else if (type === 'K') {
				longLink = cString(body);
			}
			continue;
		}
		const prefix = header.toString('latin1', 257, 263) === 'ustar\0' ? cString(header.subarray(345, 500)) : '';
		const shortName = cString(header.subarray(0, 100));
		const name = pax.get('path') ?? longName ?? (prefix ? `${prefix}/${shortName}` : shortName);
		const linkname = pax.get('linkpath') ?? longLink ?? cString(header.subarray(157, 257));
		const mode = parseNumber(header, 100, 8);
		pax = new Map();
		longName = undefined;
		longLink = undefined;
		if (type === '0' || type === '7') {
			const data = queue.take(size);
			queue.skip(padded - size);
			yield { type: '0', name, linkname, mode, data };
		} else {
			queue.skip(padded);
			yield { type, name, linkname, mode };
		}
	}
}

function safeRelativePath(name: string): string | undefined {
	const parts = name.replace(/\\/g, '/').split('/').filter(part => part && part !== '.');
	if (parts.includes('..')) {
		throw new Error(`Unsafe path in archive: ${name}`);
	}
	return parts.length ? parts.join('/') : undefined;
}

const CLONE_MIN = 64 * 1024;

class Extractor {
	private readonly dest: string;
	private readonly concurrency: number;
	private readonly cloneDuplicates: boolean;
	private readonly dirs = new Map<string, Promise<void>>();
	private readonly pendingFiles = new Map<string, Promise<void>>();
	/** The first file with each content, which copies of the same content clone */
	private readonly originals = new Map<string, { path: string; written: Promise<void> }>();
	private readonly waiters: (() => void)[] = [];
	private inflight = 0;
	private inflightBytes = 0;
	private error: unknown;
	readonly stats = { files: 0, hardlinks: 0, symlinks: 0, dirs: 0, bytes: 0, skipped: 0, clones: 0, clonedBytes: 0 };

	/**
	 * With a clone list, the copies of the same content are left to the caller as [original, copy]
	 * pairs, because Node's FICLONE copies them in full on APFS and Windows: `cp -c` clones them on
	 * APFS, FSCTL_DUPLICATE_EXTENTS_TO_FILE on ReFS.
	 */
	readonly cloneList: [string, string][] | undefined;

	constructor(dest: string, concurrency: number, cloneDuplicates: boolean, cloneList?: [string, string][]) {
		this.dest = dest;
		this.concurrency = concurrency;
		this.cloneDuplicates = cloneDuplicates;
		this.cloneList = cloneList;
	}

	async add(entry: TarEntry): Promise<void> {
		if (this.error) {
			throw this.error;
		}
		const name = safeRelativePath(entry.name);
		if (!name || path.posix.basename(name).startsWith('._')) {
			// macOS bsdtar stores extended attributes as AppleDouble ._ entries
			this.stats.skipped++;
			return;
		}
		const target = path.join(this.dest, name);
		const parent = path.dirname(target);
		switch (entry.type) {
			case '0': {
				const data = entry.data!;
				const mode = process.platform === 'win32' ? undefined : (entry.mode & 0o777) || 0o644;
				const key = this.cloneDuplicates && data.length >= CLONE_MIN ? `${mode}:${createHash('sha1').update(data).digest('hex')}` : undefined;
				const original = key ? this.originals.get(key) : undefined;
				if (original) {
					await this.slot(0);
					if (this.cloneList) {
						const cloneList = this.cloneList;
						this.track(Promise.all([original.written, this.ensureDir(parent)]).then(() => { cloneList.push([original.path, target]); }), 0);
					} else {
						// Clones the blocks of the original instead of writing them again where CopyFile or
						// FICLONE do: Node's FICLONE falls back to a full copy on APFS
						this.track(Promise.all([original.written, this.ensureDir(parent)]).then(() => fs.promises.copyFile(original.path, target, fs.constants.COPYFILE_FICLONE)), 0);
					}
					this.stats.clones++;
					this.stats.clonedBytes += data.length;
					return;
				}
				await this.slot(data.length);
				const written = this.ensureDir(parent).then(() => fs.promises.writeFile(target, data, { mode }));
				if (key) {
					this.originals.set(key, { path: target, written });
				}
				this.pendingFiles.set(target, written);
				this.track(written.finally(() => this.pendingFiles.delete(target)), data.length);
				this.stats.files++;
				this.stats.bytes += data.length;
				return;
			}
			case '1': {
				const source = path.join(this.dest, safeRelativePath(entry.linkname)!);
				await this.slot(0);
				const sourceWritten = this.pendingFiles.get(source) ?? Promise.resolve();
				this.track(Promise.all([sourceWritten, this.ensureDir(parent)])
					.then(() => fs.promises.link(source, target))
					.catch(() => fs.promises.copyFile(source, target)), 0);
				this.stats.hardlinks++;
				return;
			}
			case '2': {
				await this.slot(0);
				this.track(this.ensureDir(parent).then(() => fs.promises.symlink(entry.linkname, target)), 0);
				this.stats.symlinks++;
				return;
			}
			case '5':
				this.track(this.ensureDir(target), 0);
				return;
			default:
				this.stats.skipped++;
		}
	}

	async finish(): Promise<void> {
		while (this.inflight > 0) {
			await new Promise<void>(resolve => this.waiters.push(resolve));
		}
		await Promise.all(this.dirs.values());
		if (this.error) {
			throw this.error;
		}
	}

	private ensureDir(dir: string): Promise<void> {
		if (dir.length <= this.dest.length) {
			return Promise.resolve();
		}
		let created = this.dirs.get(dir);
		if (!created) {
			created = this.ensureDir(path.dirname(dir)).then(() => fs.promises.mkdir(dir).then(() => undefined, (err: NodeJS.ErrnoException) => {
				if (err.code !== 'EEXIST') {
					throw err;
				}
			}));
			this.dirs.set(dir, created);
			this.stats.dirs++;
		}
		return created;
	}

	private async slot(bytes: number): Promise<void> {
		while (this.inflight >= this.concurrency || (this.inflightBytes > 0 && this.inflightBytes + bytes > MAX_INFLIGHT_BYTES)) {
			await new Promise<void>(resolve => this.waiters.push(resolve));
		}
	}

	private track(operation: Promise<unknown>, bytes: number): void {
		this.inflight++;
		this.inflightBytes += bytes;
		operation.catch(err => {
			this.error ??= err;
		}).finally(() => {
			this.inflight--;
			this.inflightBytes -= bytes;
			this.waiters.splice(0).forEach(resolve => resolve());
		});
	}
}

function openArchive(archive: string, decoder: string): { stream: Readable; done: Promise<void> } {
	if (decoder === 'node') {
		const file = fs.createReadStream(archive, { highWaterMark: 1024 * 1024 });
		const stream = file.pipe(zlib.createZstdDecompress({ params: { [zlib.constants.ZSTD_d_windowLogMax]: 31 } }));
		return { stream, done: Promise.resolve() };
	}
	const zstd = spawn('zstd', ['-d', '-q', '-c', '--long=31', archive], { stdio: ['ignore', 'pipe', 'inherit'] });
	const done = once(zstd, 'exit').then(([code]) => {
		if (code !== 0) {
			throw new Error(`zstd exited with ${code}`);
		}
	});
	return { stream: zstd.stdout!, done };
}

function freeBytes(dir: string): number | undefined {
	try {
		const stats = fs.statfsSync(dir);
		return stats.bavail * stats.bsize;
	} catch {
		return undefined;
	}
}

async function extract(args: Args): Promise<void> {
	const dest = path.resolve(arg(args, 'dest'));
	const concurrency = Number(arg(args, 'concurrency', '64'));
	const statsFile = args.get('stats')?.[0];
	const start = performance.now();
	// mkdir fails with EPERM for the root of a Windows drive, even with recursive
	if (!fs.statSync(dest, { throwIfNoEntry: false })?.isDirectory()) {
		await fs.promises.mkdir(dest, { recursive: true });
	}
	const freeBefore = freeBytes(dest);
	const { stream, done } = openArchive(path.resolve(arg(args, 'archive')), arg(args, 'decoder', 'cli'));
	const cloneListFile = args.get('clone-list')?.[0];
	const extractor = new Extractor(dest, concurrency, arg(args, 'clone-duplicates', 'false') === 'true' || !!cloneListFile, cloneListFile ? [] : undefined);
	for await (const entry of readTar(stream)) {
		await extractor.add(entry);
	}
	await extractor.finish();
	// The rest of the stream is the end-of-archive padding, which fits in the pipe buffer
	await done;
	stream.destroy();
	if (cloneListFile) {
		fs.writeFileSync(cloneListFile, extractor.cloneList!.map(([original, target]) => `${original}\t${target}\n`).join(''));
	}
	const freeAfter = freeBytes(dest);
	const result = {
		...extractor.stats,
		// Less than bytes + clonedBytes when the clones share the blocks of their originals
		usedBytes: freeBefore !== undefined && freeAfter !== undefined ? freeBefore - freeAfter : undefined,
		concurrency,
		threadpool: process.env.UV_THREADPOOL_SIZE ?? '4',
		seconds: (performance.now() - start) / 1000,
	};
	console.log(JSON.stringify(result));
	if (statsFile) {
		fs.writeFileSync(statsFile, JSON.stringify(result));
	}
}

/**
 * Counts the entries of a tar archive by kind, including the metadata that macOS bsdtar adds:
 * AppleDouble ._ entries and extended attributes in pax headers.
 */
async function count(args: Args): Promise<void> {
	const { stream, done } = openArchive(path.resolve(arg(args, 'archive')), arg(args, 'decoder', 'cli'));
	const stats = { entries: 0, files: 0, hardlinks: 0, symlinks: 0, dirs: 0, other: 0, appleDouble: 0, paxHeaders: 0, xattrRecords: 0, bytes: 0 };
	const onPax = (records: ReadonlyMap<string, string>) => {
		stats.paxHeaders++;
		stats.xattrRecords += [...records.keys()].filter(key => /xattr|ACL|fflags/i.test(key)).length;
	};
	for await (const entry of readTar(stream, onPax)) {
		stats.entries++;
		if (path.posix.basename(entry.name).startsWith('._')) {
			stats.appleDouble++;
			continue;
		}
		switch (entry.type) {
			case '0': stats.files++; stats.bytes += entry.data!.length; break;
			case '1': stats.hardlinks++; break;
			case '2': stats.symlinks++; break;
			case '5': stats.dirs++; break;
			default: stats.other++;
		}
	}
	await done;
	stream.destroy();
	console.log(JSON.stringify(stats));
	const statsFile = args.get('stats')?.[0];
	if (statsFile) {
		fs.writeFileSync(statsFile, JSON.stringify(stats));
	}
}

async function move(args: Args): Promise<void> {
	const from = path.resolve(arg(args, 'from'));
	const to = path.resolve(arg(args, 'to'));
	const roots = fs.readFileSync(arg(args, 'roots'), 'utf8').split(/\r?\n/).filter(Boolean);
	const start = performance.now();
	let moved = 0;
	const skipped: string[] = [];
	for (const root of roots) {
		const target = path.join(to, root);
		if (fs.existsSync(target)) {
			// A test fixture that the repository tracks
			skipped.push(root);
			continue;
		}
		fs.mkdirSync(path.dirname(target), { recursive: true });
		fs.renameSync(path.join(from, root), target);
		moved++;
	}
	console.log(`Moved ${moved} node_modules folders in ${((performance.now() - start) / 1000).toFixed(1)}s, skipped ${skipped.length}: ${skipped.join(', ')}`);
}

/** Lists the files under the node_modules folders of `root`, skipping the large folders that hold none */
async function listNodeModules(root: string): Promise<string[]> {
	const files: string[] = [];
	const visit = async (dir: string, inNodeModules: boolean): Promise<void> => {
		const entries = await fs.promises.readdir(dir, { withFileTypes: true });
		await Promise.all(entries.map(async entry => {
			const full = path.join(dir, entry.name);
			// A node_modules folder may itself be a link, as in some worktrees
			const isDirectory = entry.isDirectory() || (!inNodeModules && entry.name === 'node_modules' && entry.isSymbolicLink() && fs.statSync(full).isDirectory());
			if (isDirectory) {
				if (!inNodeModules && dir === root && ['.git', 'out', '.build', 'src'].includes(entry.name)) {
					return;
				}
				await visit(full, inNodeModules || entry.name === 'node_modules');
			} else if (inNodeModules && entry.isFile()) {
				files.push(full);
			}
		}));
	};
	await visit(root, false);
	return files;
}

/** Reads every file of the node_modules folders of `--root` with 16 reads in flight */
async function read(args: Args): Promise<void> {
	const root = path.resolve(arg(args, 'root'));
	const start = performance.now();
	const files = await listNodeModules(root);
	const listed = (performance.now() - start) / 1000;
	let next = 0;
	let bytes = 0;
	await Promise.all(Array.from({ length: 16 }, async () => {
		while (next < files.length) {
			const data = await fs.promises.readFile(files[next++]);
			bytes += data.length;
		}
	}));
	console.log(JSON.stringify({ files: files.length, bytes, listSeconds: listed, seconds: (performance.now() - start) / 1000 }));
}

//#endregion

const [command, ...rest] = process.argv.slice(2);
const commands: Record<string, (args: Args) => Promise<void>> = { pack, extract, count, move, read };
const main = commands[command];
if (!main) {
	console.error(`Usage: node archive.ts ${Object.keys(commands).join('|')} ...`);
	process.exit(1);
}
main(parseArgs(rest)).catch(err => {
	console.error(err);
	process.exit(1);
});
